def IntervalUpsets (P : Type*) [PartialOrder P] :=
  {W : Set {st : P × P // st.1 ≤ st.2} //
    ∀ i ∈ W, ∀ j, j.val.1 ≤ i.val.1 → i.val.2 ≤ j.val.2 → j ∈ W}

